import json
import math
import random
import time

import dimod


def _anneal_read(bqm, initial_sample, temperatures, rng, evaluate):
    """Return the lowest-energy state visited during one annealing read."""
    sample = initial_sample.copy()
    variables = list(bqm.variables)
    current_energy = evaluate(sample)
    best_sample = sample.copy()
    best_energy = current_energy

    for temperature in temperatures:
        rng.shuffle(variables)
        for variable in variables:
            sample[variable] ^= 1
            candidate_energy = evaluate(sample)
            delta = candidate_energy - current_energy

            if delta <= 0.0 or rng.random() < math.exp(-delta / temperature):
                current_energy = candidate_energy
                if current_energy < best_energy:
                    best_sample = sample.copy()
                    best_energy = current_energy
            else:
                sample[variable] ^= 1

    return best_sample, best_energy


def solve_hpc_slot_scheduling():
    """
    Minimize the supplied QUBO using multistart simulated annealing.

    Each read returns its best visited state. All sample-based metrics use
    the complete, equally weighted ensemble of these returned states, with
    no feasibility filtering for violation rate or mean energy.

    Stratified initial states cover all 16 configurations of this tiny
    instance. Retaining each read's best state therefore guarantees that
    the global optimum remains represented in the returned ensemble.

    evaluation_cost counts every full QUBO objective evaluation, including
    initial states and rejected proposals. No circuit shots are used.
    """
    started = time.perf_counter()

    variables = ("x1", "x2", "x3", "x4")
    jobs = ("J1", "J2", "J3", "J4")
    priorities = (4, 6, 5, 3)
    penalty = 8
    required_slots = 2
    known_optimal_priority = 11

    linear = {
        variable: -priority - 3 * penalty
        for variable, priority in zip(variables, priorities)
    }
    quadratic = {
        (variables[i], variables[j]): 2 * penalty
        for i in range(len(variables))
        for j in range(i + 1, len(variables))
    }

    # The supplied H drops the constant 4*A = 32. Its optimal energy is
    # -43, whereas the objective plus the unexpanded penalty equals -11.
    bqm = dimod.BinaryQuadraticModel(
        linear, quadratic, 0.0, vartype=dimod.BINARY
    )

    evaluation_cost = 0

    def evaluate(sample):
        nonlocal evaluation_cost
        evaluation_cost += 1
        return float(bqm.energy(sample))

    rng = random.Random(2025)
    num_reads = 128
    num_sweeps = 128
    initial_temperature = 8.0
    final_temperature = 0.05

    temperatures = [
        initial_temperature
        * (final_temperature / initial_temperature)
        ** (sweep / (num_sweeps - 1))
        for sweep in range(num_sweeps)
    ]

    returned_samples = []
    returned_energies = []

    for read in range(num_reads):
        initial_state = read % (1 << len(variables))
        initial_sample = {
            variable: (initial_state >> i) & 1
            for i, variable in enumerate(variables)
        }
        sample, energy = _anneal_read(
            bqm, initial_sample, temperatures, rng, evaluate
        )
        returned_samples.append(sample)
        returned_energies.append(energy)

    feasible_samples = [
        sample
        for sample in returned_samples
        if sum(sample.values()) == required_slots
    ]

    if not feasible_samples:
        raise RuntimeError("The annealing workflow returned no feasible sample.")

    def scheduling_priority(sample):
        return sum(
            priority * sample[variable]
            for variable, priority in zip(variables, priorities)
        )

    best_sample = max(feasible_samples, key=scheduling_priority)
    achieved_priority = scheduling_priority(best_sample)
    selected_jobs = [
        job
        for variable, job in zip(variables, jobs)
        if best_sample[variable] == 1
    ]

    results = {
        "feasible_objective_quality": (
            achieved_priority / known_optimal_priority
        ),
        "constraint_violation_rate": (
            (num_reads - len(feasible_samples)) / num_reads
        ),
        "penalty_adjusted_qubo_energy": (
            math.fsum(returned_energies) / num_reads
        ),
        "runtime": 0.0,
        "evaluation_cost": evaluation_cost,
        "achieved_priority": achieved_priority,
        "selected_jobs": selected_jobs,
    }
    results["runtime"] = time.perf_counter() - started
    return results


if __name__ == "__main__":
    print(json.dumps(solve_hpc_slot_scheduling(), indent=2))

